~~~go
rows, err := db.QueryContext(ctx,
    `SELECT id, email FROM users WHERE active = $1 ORDER BY id`, true)
if err != nil { return err }
defer rows.Close()

for rows.Next() {
    var u User
    if err := rows.Scan(&u.ID, &u.Email); err != nil { return err }
    users = append(users, u)
}
return rows.Err()
~~~

